// Map the form dropdown selection to our API category
const categoryMap = {
  'Pipeline Snapshot — Lifecycle stage distribution': 'pipeline_snapshot',
  'Who to Contact Today — Prioritized outreach list': 'who_to_contact',
  'Daily Summary — Today\'s orders and activity': 'daily_summary',
  'Order Analytics — Top dishes, revenue, trends': 'order_analytics',
  'Campaign Performance — Email campaign stats': 'campaign_performance',
  'Customer Lookup — Look up a specific customer': 'customer_lookup',
  'Communication History — SMS/call history for a customer': 'communication_history',
  'Ask Anything (AI) — Free-form question answered by AI': 'free_form',
};

const formCategory = $input.first().json['Query Category'];
const category = categoryMap[formCategory] || 'free_form';

return [{
  json: {
    category: category,
    question: $input.first().json['Your Question or Details'] || '',
    contact_email: $input.first().json['Customer Email (if looking up a specific customer)'] || null,
    original_category: formCategory,
  }
}];

// Format the API response for display on the form completion page
const response = $input.first().json;
const answer = response.answer || 'No answer received.';
const category = response.category || 'unknown';
const question = response.question || '';

// Build a formatted response
let formatted = '';
formatted += '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n';
formatted += 'DabbahWala Marketing Intelligence\n';
formatted += '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n';
formatted += 'Category: ' + category.replace(/_/g, ' ').toUpperCase() + '\n';
if (question) {
  formatted += 'Question: ' + question + '\n';
}
formatted += '\n' + answer + '\n';
formatted += '\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n';
formatted += 'Powered by DabbahWala Intelligence Engine\n';

return [{
  json: {
    formatted_answer: formatted,
    raw_answer: answer,
    category: category,
    question: question,
    timestamp: new Date().toISOString(),
  }
}];
